import {mergeAccountSync} from './sync-model.js';
import {catalog,rune,championName,runeSignature,validatePage,refreshCatalog,SHARDS,SHARD_ROWS} from './catalog.js';
import {KEY,VERSION,DIVISIONS,TIERS,uid,clone,seed,migrate,validate,integer,number,profileURL,totals,rankAt,rankScore,stats,interval,filtered,percent} from './model.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>v===null||v===undefined?'—':typeof v==='number'?v.toLocaleString('en-US',{maximumFractionDigits:d}):esc(v),signed=v=>v===null?'—':(v>=0?'+':'')+fmt(v),wr=v=>v===null?'—':fmt(v)+'%',date=t=>new Date(t).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}),day=t=>new Date(t).toLocaleDateString('en-CA'),inputTime=t=>{const d=new Date(t);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,19);};
const btn=(label,action,id='',cls='secondary small')=>`<button type="button" class="button ${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const opt=(v,label,selected)=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`;
const empty=(title,sub,action='')=>`<div class="empty"><strong>${title}</strong>${sub}${action?'<div style="margin-top:15px">'+action+'</div>':''}</div>`;
const panel=(title,body,extra='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`;
const metric=(label,value,note,cls='')=>`<div class="metric"><div class="metric-label">${label}<span>↗</span></div><div class="metric-value ${cls}">${value}</div><div class="metric-note">${note}</div></div>`;
const routes=[['overview','◈','Overview'],['accounts','▤','Accounts'],['strategies','⚑','Strategy lab'],['history','≡','Match history'],['sessions','◷','Sessions'],['insights','◇','Insights'],['settings','⚙','Data & settings']];
const RESTRICTIONS={chat:['◌','Chat restriction'],suspension:['◷','Temporary suspension'],ban:['⊘','Account ban']};
let comparisonMode='enemy',comparisonPatch='',comparisonRank='';
let runeDraft=null,syncPending=null,syncBusy=false,connectionStatus=null,bulkRunning=false,bulkProgress='';
let state,blocked=false,previous=null,page=0,sort='rank',search='',f={season:'',account:'',strategy:'',region:'',patch:'',rank:'',from:'',to:''},minSample=5;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));else {const old=localStorage.getItem('jhin_tracker_v3');state=old?migrate(JSON.parse(old)):seed(await (await fetch('./legacy-seed.json')).json());localStorage.setItem(KEY,JSON.stringify(state));}}
catch(e){blocked=true;state=seed(await (await fetch('./legacy-seed.json')).json());$('#save-status').textContent='Storage needs attention';console.error('Workspace load failed',e);}
f.season=state.season;
const getRoute=()=>routes.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'overview';
function toast(msg,undo=false){$('#toast').innerHTML=`<span>${esc(msg)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),undo?12000:5000);}
function persist(next,message){if(blocked)throw Error('Saving is paused to protect existing data. Open Data & settings to recover or download a backup.');validate(next);const serialized=JSON.stringify(next);try{localStorage.setItem(KEY,serialized);}catch{throw Error('Could not save. Browser storage may be full or disabled. Your previous data is unchanged. Export a backup from Data & settings.');}previous=clone(state);state=next;$('#save-status').textContent='Saved on this browser';render();if(message)toast(message,true);}
function mutate(fn,msg){const next=clone(state);fn(next);persist(next,msg);}
const matches=()=>filtered(state,f),account=id=>state.accounts.find(a=>a.id===id),strategy=id=>state.strategies.find(t=>t.id===id),nameStrategy=id=>strategy(id)?.name||'Unassigned';
function download(value,name){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download(state,`jhin-atelier-${new Date().toISOString().slice(0,10)}.json`);toast('Backup downloaded. Keep a copy outside this browser.');}
function dialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#dialog').showModal();}
const input=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" value="${esc(value??'')}" type="${type}" ${type==='datetime-local'?'step="1"':''} ${attrs}></label>`;
const select=(name,label,options)=>`<label>${label}<select name="${name}">${options}</select></label>`;
const area=(name,label,value='',attrs='')=>`<label ${attrs}>${label}<textarea name="${name}" maxlength="5000">${esc(value)}</textarea></label>`;
const actions=(text='Save')=>`<div class="form-error" role="alert"></div><div class="form-actions">${btn('Cancel','close','','secondary')}<button class="button primary" type="submit">${text}</button></div>`;
const ranks=(value,none='Unranked')=>opt('',none,value)+DIVISIONS.map(r=>opt(r,r,value)).join('');
function renderFilters(){if(!['history','strategies','insights'].includes(getRoute())){$('#filters').innerHTML='';return;}const seasons=[...new Set([state.season,...state.accounts.map(a=>a.baselineSeason),...state.matches.map(m=>m.season)])].sort().reverse();$('#filters').innerHTML=`<div class="filters">${filterSelect('season','All seasons',seasons.map(x=>[x,x]))}${filterSelect('account','All accounts',state.accounts.map(a=>[a.id,a.name]))}${filterSelect('strategy','All strategies',state.strategies.map(a=>[a.id,a.name]))}${filterSelect('region','All servers',[...new Set(state.accounts.map(a=>a.region))].map(x=>[x,x]))}${filterSelect('patch','All patches',[...new Set(state.matches.map(m=>m.patch).filter(Boolean))].sort().map(x=>[x,x]))}${filterSelect('rank','All starting ranks',TIERS.map(x=>[x,x]).concat([['Master','Master'],['Grandmaster','Grandmaster'],['Challenger','Challenger']]))}<input aria-label="From date" title="From date" type="date" data-filter="from" value="${f.from}"><input aria-label="To date" title="To date" type="date" data-filter="to" value="${f.to}">${btn('Reset','filters')}<span class="filter-hint">${matches().length} tracked matches · starting balances excluded</span></div>`;}
function filterSelect(key,label,options){return `<select data-filter="${key}" aria-label="${label}">${opt('',label,f[key])}${options.map(([v,l])=>opt(v,l,f[key])).join('')}</select>`;}
function heading(kicker,title,sub,action=''){$('#page-title').innerHTML=`<div class="page-heading"><div><div class="kicker">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;}
function render(){const route=getRoute();$('#nav').innerHTML=routes.map(([id,icon,label])=>`<a class="nav-link ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</a>`).join('');$('#season-label').textContent='SEASON '+state.season;renderFilters();const views={overview,accounts,strategies,history,sessions,insights,settings};views[route]();if(blocked)$('#content').insertAdjacentHTML('afterbegin','<div class="notice red">Existing storage could not be loaded or written. Saving is paused. Open Data & settings to download the stored data and recover it. The visible accounts are fallback starting data.</div>');}
function overview(){$('#page-title').innerHTML=overviewSummary();const m=state.matches.filter(m=>m.season===state.season),s=stats(m);const recent=[...m].sort((a,b)=>b.ts-a.ts).slice(0,5);const streak=[...state.matches].filter(m=>m.result!=='remake').sort((a,b)=>b.ts-a.ts).slice(0,3);$('#content').innerHTML=`${streak.length===3&&streak.every(m=>m.result==='loss')?'<div class="notice red">Three consecutive losses across your accounts. A short break might help you reset.</div>':''}${latestMatchCard()}<div class="metrics">${metric('TRACKED WIN RATE',wr(s.wr),`${s.w} wins / ${s.l} losses`,s.wr>=50?'positive':'')}${metric('AGGREGATE KDA',fmt(s.kda),'Calculated from complete K / D / A','gold-text')}${metric('CS PER MINUTE',fmt(s.csMin),'Calculated from CS and game duration','positive')}${metric('MATCHES STUDIED',fmt(s.n,0),`${new Set(m.map(x=>x.accountId)).size} accounts this season`)}</div><div class="grid-two">${panel('The shape of your climb',`<div class="panel-body">${checkpointChart()}${snapshotChanges()}</div>`,'<small>Rank snapshots between syncs</small>')}${panel('Recent performances',recent.length?recent.map(recentRow).join(''):empty('Your next game starts the story.','No recorded matches in this selection.',btn('Log your first match','match','','gold small')),`<a class="text-btn" href="#history">View all ↗</a>`)}</div>${panel('Matchup & build comparisons',comparisonPanel())}${panel('Your best accounts',bestAccountCards(),`<a class="text-btn" href="#accounts">All ${state.accounts.length} accounts ↗</a>`)}<div class="help">Sync fetches recent ranked solo/duo Jhin games. Rank estimates use recorded LP and your latest checkpoint. Add a checkpoint after promotions, demotions or resets.</div>`;}
function recentRow(m){return `<div class="list-row"><div class="result-icon ${m.result==='loss'?'loss':''}">${m.result==='win'?'W':m.result==='loss'?'L':'R'}</div><div class="grow"><strong>${esc(account(m.accountId)?.name)}</strong><small>${esc(nameStrategy(m.strategyId))} · ${m.enemy?'vs '+esc(m.enemy)+' · ':''}${date(m.ts)}</small></div><div class="list-right"><strong class="${m.lp>=0?'positive':'negative'}">${signed(m.lp)} LP</strong><small>${m.duration?fmt(m.duration)+' min':'No duration'}</small></div></div>`;}
function chart(list){const m=[...list].filter(m=>m.lp!==null&&m.result!=='remake').sort((a,b)=>a.ts-b.ts);if(!m.length)return checkpointChart();const colors=['#ef4444','#fca5a5','#f5f5f5','#fb7185','#9ca3af','#b91c1c'];const ids=[...new Set(m.map(m=>m.accountId))];const series=ids.map((id,i)=>{let n=0;return {id,color:colors[i%colors.length],points:[{x:0,y:0},...m.filter(m=>m.accountId===id).map((v,j)=>({x:j+1,y:n+=v.lp}))]};});const maxX=Math.max(...series.map(s=>s.points.length-1),1),all=series.flatMap(s=>s.points.map(p=>p.y)),lo=Math.min(0,...all),hi=Math.max(1,...all),x=v=>40+v/maxX*680,y=v=>155-(v-lo)/(hi-lo)*130;return `<svg class="chart" viewBox="0 0 750 190" role="img" aria-label="Cumulative recorded LP by account, each starting at zero. Exact totals are available in Insights.">${[0,.5,1].map(t=>`<line x1="40" y1="${25+t*130}" x2="720" y2="${25+t*130}" stroke="#343434" stroke-dasharray="3 5"/><text x="0" y="${29+t*130}">${Math.round(hi-t*(hi-lo))}</text>`).join('')}${series.map(s=>`<polyline fill="none" stroke="${s.color}" stroke-width="2" points="${s.points.map(p=>x(p.x)+','+y(p.y)).join(' ')}"/>`).join('')}<text x="40" y="182">0</text><text x="655" y="182">${maxX} games</text></svg><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(account(s.id)?.name)}</span>`).join('')}</div>`;}
function rankSort(a,b){const ar=rankAt(state,a),br=rankAt(state,b);return (rankScore(br.rank,br.lp??0)??-1)-(rankScore(ar.rank,ar.lp??0)??-1);}
function accountTable(list){if(!list.length)return empty('No accounts here.','Add an account to start tracking.',btn('Add account','account','','gold small'));return `<div class="table-scroll"><table><thead><tr><th>Account</th><th>Server</th><th>Rank / LP</th><th>W/L</th><th>Win rate</th><th class="sync-label">Synchronization / profiles</th></tr></thead><tbody>${list.map(a=>{const t=totals(state,a),r=rankAt(state,a),p=percent(t.wins,t.losses);return `<tr><td><div class="account-name"><button type="button" class="avatar" data-action="copy-account" data-id="${esc(a.id)}" aria-label="Copy account name: ${esc(a.name)}" title="Copy account name: ${esc(a.name)}">IV</button><div><strong class="nickname-line">${esc(a.riotId||a.name)} ${honorBadges(a)} ${state.matches.some(m=>m.accountId===a.id&&day(m.ts)===day(Date.now()))?'<span class="pill muted">Played today</span>':''} ${a.archived?'<span class="pill muted">Archived</span>':''}</strong><small>${esc(a.name)} · LVL ${a.level}${a.lastSync?' · <span class="account-sync-time">synced '+date(a.lastSync)+'</span>':''}</small></div></div></td><td><span class="pill muted">${esc(a.region)}</span></td><td><span class="rank rank-${esc(r.rank.split(' ')[0].toLowerCase())}"><svg class="rank-emblem" viewBox="0 0 32 36" aria-hidden="true"><path d="M16 2 29 9 26 25 16 34 6 25 3 9Z"/><path d="m9 13 7-6 7 6-7 13Z"/><path d="M8 28 2 19M24 28l6-9"/></svg>${esc(r.rank)}</span><div class="help">${r.lp===null?'LP unknown':fmt(r.lp,0)+' LP'}${r.estimated?' · estimated':''}</div></td><td><span class="positive">${t.wins}</span> <span style="color:var(--muted)">/ ${t.losses}</span></td><td class="win-rate ${p===null?'wr-unknown':p>50?'wr-high':p===50?'wr-even':'wr-low'}">${wr(p)}<span class="bar"><i style="width:${p||0}%"></i></span></td><td><div class="row-actions">${btn('↻ Sync','sync',a.id,'primary small')}${a.profile?`<a class="button secondary small" href="${esc(a.profile)}" target="_blank" rel="noopener noreferrer">OP.GG ↗</a>`:btn('＋ OP.GG','profile',a.id)}${a.leagueofgraphs?`<a class="button secondary small" href="${esc(a.leagueofgraphs)}" target="_blank" rel="noopener noreferrer">League of Graphs ↗</a>`:btn('＋ League of Graphs','profile',a.id)}${btn('＋ Match','match',a.id,'gold small')}${btn('Edit','account',a.id)}</div></td></tr>`;}).join('')}</tbody></table></div>`;}
function accounts(){$('#page-title').innerHTML=`<div class="accounts-banner"><h1>Accounts</h1><div class="row-actions"><button type="button" class="button primary" data-action="sync-all" ${bulkRunning?'disabled aria-busy="true"':''}>${bulkRunning?'Syncing…':'↻ Sync all accounts'}</button>${btn('＋ Add account','account','','primary')}</div></div>`;let list=state.accounts.filter(a=>(a.name+' '+a.riotId).toLowerCase().includes(search.toLowerCase()));list.sort(sort==='rank'?rankSort:sort==='wr'?(a,b)=>(percent(...Object.values(totals(state,b)))??-1)-(percent(...Object.values(totals(state,a)))??-1):sort==='level'?(a,b)=>(Number(b.level)||0)-(Number(a.level)||0)||a.name.localeCompare(b.name):(a,b)=>a.name.localeCompare(b.name));$('#content').innerHTML=`<div role="status" aria-live="polite" class="help">${esc(bulkProgress)}</div><div class="filters"><input id="account-search" class="search" aria-label="Search accounts" placeholder="Search accounts…" value="${esc(search)}"><select id="account-sort" aria-label="Sort accounts">${opt('rank','Highest rank',sort)}${opt('wr','Highest win rate',sort)}${opt('level','Highest level',sort)}${opt('name','Account name',sort)}</select><span class="filter-hint">${list.length} accounts · ${esc(state.season)} totals</span></div>${panel('Account roster',accountTable(list),'<small>Edit an account to add both profile links</small>')}${panel('Rank checkpoints & goals',state.accounts.filter(a=>!a.archived).map(a=>{const r=rankAt(state,a),goal=rankScore(a.goalRank,a.goalLp),current=rankScore(r.rank,r.lp);const remaining=goal!==null&&current!==null?Math.max(0,goal-current):null;const sample=stats(state.matches.filter(m=>m.accountId===a.id&&m.season===state.season));const checkpoint=state.checkpoints.filter(c=>c.accountId===a.id).sort((a,b)=>b.ts-a.ts)[0];return `<div class="list-row"><div class="grow"><strong>${esc(a.name)}</strong><small>${a.goalRank?'Target: '+esc(a.goalRank)+' · '+a.goalLp+' LP'+(remaining!==null?' · '+remaining+' estimated LP to go'+(sample.lpGame>0?' · about '+Math.ceil(remaining/sample.lpGame)+' games at recorded pace':''):''):'No target set · add one in Edit'}${checkpoint?' · Latest checkpoint '+date(checkpoint.ts):''}</small></div>${btn('Set checkpoint','checkpoint',a.id)}</div>`;}).join(''))}`;}
function strategies(){heading('EXPERIMENT WITH INTENT','Your <em>strategy lab.</em>','Save your actual rune pages. Matches with the same setup can be assigned automatically.',btn('＋ New rune page / strategy','strategy','','primary'));const m=matches();$('#content').innerHTML=`<div class="notice">Comparisons use recorded games only. Different ranks, servers and patches can affect results. Small samples are exploratory.</div>${state.strategies.length?'<div class="cards">'+state.strategies.map(t=>{const s=stats(m.filter(m=>m.strategyId===t.id)),ci=interval(s.w,s.n);return `<section class="strategy-card"><span class="pill ${t.archived?'muted':''}">${t.archived?'ARCHIVED':s.n<minSample?'EARLY OBSERVATIONS':'IN STUDY'}</span><h2>${esc(t.name)}</h2><p>${esc(t.description)||'A saved setup for your Jhin games.'}</p>${runeSummary(t.runePage)}<div class="strategy-numbers"><div><strong class="positive">${wr(s.wr)}</strong><small>WIN RATE · ${s.n} GAMES</small></div><div><strong class="gold-text">${fmt(s.kda)}</strong><small>AGGREGATE KDA</small></div></div><div class="help">${s.w} wins / ${s.l} losses · ${fmt(s.csMin)} CS / min<br>95% win-rate interval: ${ci?fmt(ci[0],0)+'–'+fmt(ci[1],0)+'%':'—'}</div><div class="row-actions">${btn('Edit strategy','strategy',t.id)}${btn(t.archived?'Restore':'Archive','archive-strategy',t.id)}</div></section>`;}).join('')+'</div>':panel('Build your first experiment',empty('What will you test?','For example: a build order, a keystone, or a lane plan.<br>Each match keeps its own strategy even if the account default changes.',btn('Create a strategy','strategy','','gold')))}${panel('Comparison table',comparison(m,'strategyId'),'<small>LP metrics include only games with LP entered</small>')}`;}
function comparison(m,key){const groups=key==='accountId'?state.accounts.map(a=>[a.id,a.name]):state.strategies.map(t=>[t.id,t.name]).concat([['','Unassigned']]);const rows=groups.map(([id,name])=>({name,s:stats(m.filter(m=>m[key]===id))})).filter(x=>x.s.n).sort((a,b)=>(b.s.lpGame??-Infinity)-(a.s.lpGame??-Infinity));if(!rows.length)return empty('No comparisons yet.','Record matches to see your strategies side by side.');return `<div class="table-scroll"><table class="insights-table"><thead><tr><th>${key==='accountId'?'Account':'Strategy'}</th><th>Games</th><th>Win rate</th><th>Net LP</th><th>LP/game</th><th>LP/hour</th><th>LP coverage</th><th>Evidence</th></tr></thead><tbody>${rows.map(({name,s})=>`<tr><td>${esc(name)}</td><td>${s.n}</td><td>${wr(s.wr)}</td><td class="${s.net>=0?'positive':'negative'}">${signed(s.net)}</td><td>${signed(s.lpGame)}</td><td>${signed(s.lpHour)}</td><td>${s.lpN}/${s.n}</td><td><span class="pill muted">${s.n<minSample?'Small sample':'Compare context'}</span></td></tr>`).join('')}</tbody></table></div>`;}
function history(){heading('THE RECORD','Every shot <em>on record.</em>','Edit mistakes, preserve the details, and keep all your statistics in sync.',btn('＋ Log match','match','','primary'));const list=matches().sort((a,b)=>b.ts-a.ts),pages=Math.max(1,Math.ceil(list.length/15));page=Math.min(page,pages-1);$('#content').innerHTML=panel('Match journal',list.length?`<div class="table-scroll"><table><thead><tr><th>Result / time</th><th>Account</th><th>Strategy</th><th>LP</th><th>Lane / runes</th><th>K / D / A · CS</th><th>Time</th><th>Details</th><th>Actions</th></tr></thead><tbody>${list.slice(page*15,page*15+15).map(m=>`<tr><td><span class="pill ${m.result==='loss'?'loss':m.result==='remake'?'muted':''}">${m.result.toUpperCase()}</span><div class="help">${date(m.ts)}</div></td><td>${esc(account(m.accountId)?.name)}<div class="help">${esc(m.season)}${m.patch?' · '+esc(m.patch):''}</div></td><td>${esc(nameStrategy(m.strategyId))}<div class="help">${esc(state.sessions.find(s=>s.id===m.sessionId)?.name||'No session')}</div></td><td class="${m.lp>=0?'positive':'negative'}">${signed(m.lp)}</td><td>${esc(m.enemy||'—')}<div class="help">Support: ${esc(m.support||'—')}<br>${esc(m.keystone||'No keystone')}</div></td><td>${[m.kills,m.deaths,m.assists].map(v=>v===null?'—':v).join(' / ')}<div class="help">${m.cs===null?'—':m.cs} CS${m.cs!==null&&m.duration?' · '+fmt(m.cs/m.duration)+' / min':''}</div></td><td>${m.duration?fmt(m.duration)+'m':'—'}<div class="help">${m.queueMinutes!==null?fmt(m.queueMinutes)+'m queue':''}</div></td><td class="history-note">${esc(m.note||'—')}${m.build?'<br>Build: '+esc(m.build):''}${m.runes?'<br>Runes: '+esc(m.runes):''}</td><td><div class="row-actions">${m.matchId&&account(m.accountId)?.puuid?btn('Review lane','review-lane',m.id):''}${btn('Edit','edit-match',m.id)}${btn('Delete','delete-match',m.id,'danger small')}</div></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${list.length} matches · Page ${page+1} of ${pages}</span><button class="button secondary small" data-action="prev" ${page===0?'disabled':''}>← Previous</button><button class="button secondary small" data-action="next" ${page===pages-1?'disabled':''}>Next →</button></div>`:empty('A clean page.','No matches match your filters.',btn('Log a match','match','','gold small')));}
function sessions(){heading('THE RHYTHM','Play with <em>intention.</em>','Group your games into sessions. Notice when your best performances happen.',btn('＋ Start session','session','','primary'));const list=[...state.sessions].sort((a,b)=>b.start-a.start);$('#content').innerHTML=list.length?list.map(x=>{const m=state.matches.filter(m=>m.sessionId===x.id),s=stats(m);return `<section class="panel session-card"><div class="panel-head"><div><h2>${esc(x.name)} ${x.end===null?'<span class="pill">IN PROGRESS</span>':''}</h2><div class="help">${date(x.start)}${x.end?' — '+date(x.end):''} · ${esc(x.season)}</div></div><div class="row-actions">${btn('Edit','edit-session',x.id)}${x.end===null?btn('End session','end-session',x.id,'gold small'):''}</div></div><div class="panel-body"><span>Games<strong>${s.n}</strong></span><span>W / L<strong>${s.w} / ${s.l}</strong></span><span>Net LP<strong>${signed(s.net)}</strong></span><span>LP / hour<strong>${signed(s.lpHour)}</strong></span><span>Elapsed<strong>${fmt(((x.end||Date.now())-x.start)/60000,0)} min</strong></span></div>${m.length?m.map(recentRow).join(''):empty('Session ready.','Your next match will be assigned to this session automatically.')}</section>`;}).join(''):panel('Your sessions',empty('Find your rhythm.','Start a session before you play. You can log across multiple accounts.',btn('Start session','session','','gold small')));}
function groupTable(m,key,title){const keys=[...new Set(m.map(x=>x[key]).filter(Boolean))];return panel(title,keys.length?`<div class="table-scroll"><table><thead><tr><th>${title}</th><th>Games</th><th>Win rate</th><th>Net LP</th><th>Evidence</th></tr></thead><tbody>${keys.map(k=>({k,s:stats(m.filter(x=>x[key]===k))})).sort((a,b)=>(b.s.wr??0)-(a.s.wr??0)).map(({k,s})=>`<tr><td>${esc(k)}</td><td>${s.n}</td><td>${wr(s.wr)}</td><td>${signed(s.net)}</td><td><span class="pill muted">${s.n<minSample?'Small sample':'Compare context'}</span></td></tr>`).join('')}</tbody></table></div>`:empty('No details yet.','Add these details when recording a match.'));}
function insights(){heading('READ BETWEEN THE GAMES','Patterns, <em>not promises.</em>','Use comparable conditions and enough games before choosing your next approach.');const m=matches(),s=stats(m);$('#content').innerHTML=`<div class="filters"><label class="inline-fields">Small-sample threshold <input id="min-sample" type="number" min="1" max="1000" value="${minSample}" style="width:80px"></label><span class="filter-hint">Threshold is a display aid, not a significance test.</span></div><div class="metrics">${metric('CS PER MINUTE',fmt(s.csMin),'Games with CS and duration')}${metric('AGGREGATE KDA',fmt(s.kda),'(Total kills + assists) / deaths')}${metric('LP PER GAME',signed(s.lpGame),`${s.lpN} games with known LP`)}${metric('TRACKED WIN RATE',wr(s.wr),`${s.n} games · remakes excluded`)}</div>${panel('Accounts compared',comparison(m,'accountId'))}${panel('Strategies compared',comparison(m,'strategyId'))}<div class="grid-two">${groupTable(m,'enemy','Enemy ADC')}${groupTable(m,'support','Allied support')}</div>${groupTable(m,'keystone','Keystone')}<div class="grid-two">${panel('Cumulative win rate',`<div class="panel-body">${performanceChart(m,'wr')}</div>`)}${panel('CS per minute',`<div class="panel-body">${performanceChart(m,'cs')}</div>`)}</div>${panel('K / D / A across matches',`<div class="panel-body">${performanceChart(m,'kda')}</div>`)}<div class="notice">LP/hour uses games with both LP and duration; entered queue time is included. Rank filters require a known baseline or checkpoint at match time. Rune trees imported from the old tracker remain coarse labels. Win-rate intervals in Strategy lab use the Wilson 95% method.</div>`;}
function settings(){heading('KEEP YOUR WORK','Your data. <em>Your control.</em>','Back up regularly. Your games are stored in this browser, on this site.');$('#content').innerHTML=`<div class="notice">Champion & rune catalog: Riot Data Dragon ${esc(catalog.version)} · ${catalog.champions.length} champions. ${btn('↻ Refresh catalog','refresh-catalog')}</div><div class="settings-grid">${panel('Backups & migration',`<div class="panel-body"><p>Export a complete JSON backup, including accounts, starting balances, matches, sessions, strategies and checkpoints. Import replaces this workspace after validation and confirmation; a download of your current workspace is created first.</p><div class="row-actions">${btn('↓ Export backup','backup','','gold')}<label class="button secondary file-label">↑ Import JSON<input type="file" id="import-file" accept="application/json,.json"></label></div><div style="margin-top:15px"><a class="button secondary" href="jhin-atelier-source.zip" download>↓ Download source code</a></div><h3>Coming from the original tracker?</h3><p>Import its saved <code>jhin_tracker_v3</code> JSON. Original account totals become starting balances after subtracting imported history. Separate manual counters are retained as a legacy archive.</p>${btn('Paste old tracker JSON','paste-import')}${state.legacyAggregates?'<div style="margin-top:14px">'+btn('Download legacy counters','legacy')+'</div>':''}${blocked?'<div class="notice red" style="margin-top:20px">Saving is paused. Download the original stored data before recovering.</div>'+btn('Download stored data','raw-backup')+' '+btn('Recover from backup','recover','','danger'):''}</div>`)}${panel('Seasons & archives',`<div class="panel-body"><p>Change the active season without deleting history. Previous matches and starting balances remain available in filters. End your active session before starting a new season.</p><form data-form="season"><label>Active season<input name="season" required maxlength="40" value="${esc(state.season)}"></label>${actions('Set season')}</form><div class="help">Archiving accounts and strategies hides them from new-entry defaults; previous records remain intact.</div></div>`)}${panel('Profile links & automatic imports',`<div class="panel-body"><p>Each account can store an OP.GG profile and a League of Graphs profile. Use Edit in Accounts to add or change the links. They open in a new tab.</p><div class="step"><b>01</b><div><strong>Profile shortcuts · available</strong><br>Open your exact profile with one click.</div></div><div class="step"><b>02</b><div><strong>On-demand Riot sync · ready to connect</strong><br>Save a Riot API key securely once, then use Sync on any account. Fetch results, K/D/A, CS, duration, runes, items and current rank directly from Riot.</div></div><div class="step"><b>03</b><div><strong>One-time account setup</strong><br>Each account needs its Riot ID + #tag and server. Development API keys expire every 24 hours; a personal key can be requested from Riot for longer-term use. Historic per-game LP is not supplied and remains optional.</div></div>${btn('Connect / replace Riot API key','connect','','primary')} ${btn('Remove saved key','disconnect','','secondary')} <a href="https://developer.riotgames.com/docs/portal" target="_blank" rel="noopener noreferrer" class="text-btn">Riot developer documentation ↗</a></div>`)}${panel('Storage & interpretation',`<div class="panel-body"><p>No cloud game database is connected. Another browser, device, domain or private window has a different workspace. Export/import transfers your data.</p><p>Rank changes are estimated from your recorded LP; actual promotion, demotion and protection rules can change the result. Set a dated checkpoint when the game shows a different rank. Higher apex tiers require manual checkpoints.</p><p>Starting W/L balances are included in account tables only. Analytics use recorded matches. Unknown LP, K/D/A and time stay unknown.</p>${state.warnings?.length?'<h3>Migration notes</h3>'+state.warnings.map(w=>'<p>'+esc(w)+'</p>').join(''):''}<h3>Conflicting tabs</h3><p>If another tab changes the workspace, this tab pauses saving until you reload, so it cannot silently overwrite those changes.</p></div>`)}</div>`;}
function accountDialog(id='',profilesOnly=false){const a=account(id)||{name:'',riotId:'',region:'LAN',level:30,rank:'Unranked',lp:null,baseWins:0,baseLosses:0,baselineSeason:state.season,strategyId:'',profile:'',leagueofgraphs:'',goalRank:'',goalLp:0,archived:false};if(profilesOnly){dialog('Link your account',`<p class="subtitle" style="margin:0 0 20px">${esc(a.name)} · Profile links are shortcuts. They do not import games automatically.</p><form data-form="profile" data-id="${esc(id)}"><div class="fields">${input('profile','OP.GG profile URL',a.profile,'url','maxlength="500" placeholder="https://op.gg/lol/summoners/…" class="full"')}${input('leagueofgraphs','League of Graphs profile URL',a.leagueofgraphs,'url','maxlength="500" placeholder="https://www.leagueofgraphs.com/summoner/…"')}</div>${actions('Save profile links')}</form>`);return;}dialog(id?'Edit account':'Add an account',`<form data-form="account" data-id="${esc(id)}"><div class="form-caption">Identity & default strategy</div><div class="fields">${input('name','Account label',a.name,'text','required maxlength="150"')}${input('riotId','Riot ID (include #tag when known)',a.riotId,'text','maxlength="150"')}${select('region','Server',['LAN','LAS','NA','EUW','EUNE','KR','BR','OCE','TR','RU','JP','SEA','TW','VN','ME'].map(x=>opt(x,x,a.region)).join(''))}${input('level','Account level',a.level,'number','required min="1" max="10000" step="1"')}${select('strategyId','Default strategy',opt('','Unassigned',a.strategyId)+state.strategies.filter(t=>!t.archived||t.id===a.strategyId).map(t=>opt(t.id,t.name,a.strategyId)).join(''))}<label class="check-label"><input type="checkbox" name="archived" ${a.archived?'checked':''}> Archive account</label></div><hr class="form-separator"><div class="form-caption">Profile shortcuts</div><div class="fields">${input('profile','OP.GG profile URL',a.profile,'url','maxlength="500" placeholder="https://op.gg/…"')}${input('leagueofgraphs','League of Graphs profile URL',a.leagueofgraphs,'url','maxlength="500" placeholder="https://www.leagueofgraphs.com/summoner/…"')}</div><p class="help">Profile links open in a new tab. Use Sync to import games through your saved Riot connection.</p><details style="margin-top:20px"><summary>Starting balances & climb target · advanced</summary><div class="form-caption">Starting balances · not your current totals</div><div class="fields">${input('baselineSeason','Starting-balance season',a.baselineSeason,'text','required maxlength="40"')}${input('baselineTs','Starting rank timestamp',inputTime(a.baselineTs||Date.now()),'datetime-local','required')}${input('baseWins','Starting wins',a.baseWins,'number','required min="0" step="1"')}${input('baseLosses','Starting losses',a.baseLosses,'number','required min="0" step="1"')}${select('rank','Starting rank',opt('Unranked','Unranked',a.rank)+DIVISIONS.map(r=>opt(r,r,a.rank)).join(''))}${input('lp','Starting rank LP (blank = unknown)',a.lp,'number','min="0" max="100000" step="1"')}</div><p class="help">Current totals add recorded matches to these balances. To correct your current rank, use Set checkpoint in Accounts.</p><hr class="form-separator"><div class="form-caption">Climb target</div><div class="fields">${select('goalRank','Target rank',ranks(a.goalRank,'No target'))}${input('goalLp','Target LP',a.goalLp,'number','required min="0" max="100000" step="1"')}</div></details>${actions(id?'Save account':'Add account')}</form>`);}
function sessionDialog(id=''){const s=state.sessions.find(x=>x.id===id);if(!s&&state.sessions.some(x=>x.end===null)){location.hash='sessions';toast('End your active session before starting another.');return;}dialog(s?'Edit session':'Start a session',`<form data-form="session" data-id="${esc(id)}"><div class="fields"><div class="full">${input('name','Session name',s?.name||'Ranked · '+new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short'}),'text','required maxlength="100"')}</div>${input('start','Start time',inputTime(s?.start||Date.now()),'datetime-local','required')}${input('end','End time (blank = active)',s?.end?inputTime(s.end):'','datetime-local')}${input('season','Season',s?.season||state.season,'text','required maxlength="100"')}</div><p class="help">New matches default to your active session. Assign older matches by editing their session and time.</p>${actions(s?'Save session':'Start session')}</form>`);}
function checkpointDialog(id){const a=account(id),r=rankAt(state,a);dialog('Set an exact rank checkpoint',`<form data-form="checkpoint" data-id="${esc(id)}"><p class="subtitle" style="margin:0 0 20px">${esc(a.name)} · Use the rank and LP shown in the League client. This corrects future estimates without changing previous match LP.</p><div class="fields">${select('rank','Rank',DIVISIONS.map(x=>opt(x,x,r.rank)).join(''))}${input('lp','LP',r.lp??0,'number','required min="0" max="100000" step="1"')}${input('ts','Checkpoint time',inputTime(Date.now()),'datetime-local','required')}${input('season','Season',state.season,'text','required maxlength="40"')}</div>${actions('Save checkpoint')}</form>`);}
async function importData(raw,recovery=false){let parsed;try{parsed=JSON.parse(raw);}catch{throw Error('This file is not valid JSON.');}const next=parsed.version===VERSION?validate(parsed):migrate(parsed);if(!confirm(`Replace this workspace with ${next.accounts.length} accounts and ${next.matches.length} matches? A backup of the current workspace will download first.`))return false;if(recovery){download(localStorage.getItem(KEY)||localStorage.getItem('jhin_tracker_v3')||JSON.stringify(state),'jhin-before-recovery.json');}else backup();const oldBlocked=blocked;try{blocked=false;persist(next,'Workspace imported.');f.season=state.season;render();}catch(e){blocked=oldBlocked;throw e;}return true;}
function deleteMatch(id){const m=state.matches.find(m=>m.id===id);dialog('Delete this match?',`<p class="subtitle">${esc(account(m.accountId)?.name)} · ${date(m.ts)} · ${m.result}<br>The match will be removed from all calculated statistics. Undo is available after deletion.</p><div class="form-actions">${btn('Keep match','close')}${btn('Delete match','confirm-delete',id,'danger')}</div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{switch(action){case 'copy-account':copyAccountName(id,b);break;case 'sync-all':syncAllAccounts();break;case 'sync':awaitSync(id);break;case 'connect':connectDialog();break;case 'disconnect':api('/api/connection',{method:'DELETE'}).then(()=>toast('Saved Riot API key removed. Account links and matches are preserved.')).catch(e=>toast(e.message));break;case 'confirm-sync':applySync();break;case 'more-sync':awaitSync(id,true);break;case 'refresh-catalog':refreshCatalog().then(()=>{render();toast((catalog.stale?'Using bundled champion and rune snapshot ':'Champion and rune catalog updated to ')+catalog.version);}).catch(e=>toast(e.message));break;case 'pick-rune':pickRune(b);break;case 'assign-unassigned':assignDialog();break;case 'match':matchDialog('',id);break;case 'review-lane':reviewLane(id);break;case 'edit-match':matchDialog(id);break;case 'honor':honorDialog(id);break;case 'account':accountDialog(id);break;case 'profile':accountDialog(id,true);break;case 'strategy':strategyDialog(id);break;case 'archive-strategy':mutate(s=>{const t=s.strategies.find(t=>t.id===id);t.archived=!t.archived;},'Strategy updated.');break;case 'checkpoint':checkpointDialog(id);break;case 'session':sessionDialog();break;case 'edit-session':sessionDialog(id);break;case 'end-session':mutate(s=>{const x=s.sessions.find(x=>x.id===id);const last=Math.max(x.start,...s.matches.filter(m=>m.sessionId===id).map(m=>m.ts));x.end=Math.max(Date.now(),last);},'Session completed.');break;case 'go-sessions':location.hash='sessions';break;case 'go-accounts':location.hash='accounts';break;case 'close':$('#dialog').close();break;case 'backup':backup();break;case 'raw-backup':download(localStorage.getItem(KEY)||localStorage.getItem('jhin_tracker_v3')||'{}','jhin-stored-recovery.json');break;case 'recover':dialog('Recover your workspace',`<form data-form="paste-import" data-recovery="true">${area('json','Paste a valid Atelier backup or original tracker JSON')}<p class="help">The original stored data will download before replacement.</p>${actions('Validate & recover')}</form>`);break;case 'legacy':download(state.legacyAggregates,'jhin-legacy-counters.json');break;case 'paste-import':dialog('Import original tracker data',`<form data-form="paste-import">${area('json','Paste original tracker JSON')}<p class="help">This replaces the current workspace after confirmation. A backup will download first.</p>${actions('Validate & import')}</form>`);break;case 'delete-match':deleteMatch(id);break;case 'confirm-delete':mutate(s=>{s.matches=s.matches.filter(m=>m.id!==id);},'Match deleted; statistics recalculated.');$('#dialog').close();break;case 'undo':if(previous){const next=previous;persist(next,'Last action undone.');previous=null;$('#toast').innerHTML='<span>Last action undone.</span>';}break;case 'filters':f={season:state.season,account:'',strategy:'',region:'',patch:'',rank:'',from:'',to:''};page=0;render();break;case 'prev':page=Math.max(0,page-1);history();break;case 'next':page++;history();break;}}catch(err){const error=$('#dialog[open] .form-error');if(error)error.textContent=err.message;else toast(err.message);}});
document.addEventListener('change',async e=>{try{if(e.target.id==='rune-primary'||e.target.id==='rune-secondary'){const key=e.target.id==='rune-primary'?'primary':'secondary';const previousPrimary=runeDraft.primary;runeDraft[key]=Number(e.target.value);if(runeDraft.primary===runeDraft.secondary){runeDraft[key==='primary'?'secondary':'primary']=catalog.trees.find(t=>t.id!==runeDraft[key]).id;}const tree=catalog.trees.find(t=>t.id===runeDraft.primary);if(previousPrimary!==runeDraft.primary)runeDraft.primaryRunes=tree.slots.map(slot=>slot.runes[0].id);runeDraft.secondaryRunes=[];$('#rune-builder').innerHTML=runeBuilder();}if(e.target.dataset.shard){runeDraft.shards[Number(e.target.dataset.shard)]=Number(e.target.value);}if(e.target.dataset.filter){f[e.target.dataset.filter]=e.target.value;page=0;render();}if(e.target.id==='account-sort'){sort=e.target.value;accounts();}if(e.target.id==='min-sample'){minSample=integer(e.target.value,'Sample threshold',1,1000);insights();}if(e.target.name==='accountId'&&e.target.closest('[data-form="match"]')){const form=e.target.form,a=account(e.target.value);form.elements.strategyId.value=state.strategies.some(t=>t.id===a.strategyId&&!t.archived)?a.strategyId:'';}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('Backup is too large (maximum 20 MB).');await importData(await file.text(),blocked);e.target.value='';}}catch(err){const error=$('#dialog[open] .form-error');if(error)error.textContent=err.message;else toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='account-search'){search=e.target.value;const start=e.target.selectionStart;accounts();$('#account-search').focus();$('#account-search').setSelectionRange(start,start);}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form)),id=form.dataset.id,kind=form.dataset.form;const time=(raw,label)=>{const ts=new Date(raw).getTime();if(!Number.isFinite(ts))throw Error(`Enter a valid ${label}.`);return ts;};try{if(kind==='account'){const old=account(id),a={...(account(id)||{}),id:id||uid(),name:d.name.trim(),riotId:d.riotId.trim(),region:d.region,level:integer(d.level,'Level',1,10000),baseWins:integer(d.baseWins,'Starting wins'),baseLosses:integer(d.baseLosses,'Starting losses'),baselineSeason:d.baselineSeason.trim(),baselineTs:time(d.baselineTs,'starting rank time'),rank:d.rank,lp:integer(d.lp,'LP',0,d.rank==='Unranked'||DIVISIONS.indexOf(d.rank)<28?99:100000,true),strategyId:d.strategyId,profile:profileURL(d.profile),leagueofgraphs:profileURL(d.leagueofgraphs),goalRank:d.goalRank,goalLp:integer(d.goalLp,'Goal LP',0,100000),archived:!!d.archived};if(a.rank==='Unranked')a.lp=null;mutate(s=>{if(old)s.accounts[s.accounts.findIndex(a=>a.id===id)]=a;else s.accounts.push(a);},old?'Account saved.':'Account added.');}
else if(kind==='honor'){mutate(s=>{const a=s.accounts.find(a=>a.id===id);a.honorLevel=d.honorLevel===''?null:integer(d.honorLevel,'Honor level',0,5);a.restrictions=['chat','suspension','ban'].filter(k=>d[k]);a.honorLocked=!!d.honorLocked;},'Honor and restrictions saved.');}
else if(kind==='profile'){mutate(s=>{const a=s.accounts.find(a=>a.id===id);a.profile=profileURL(d.profile);a.leagueofgraphs=profileURL(d.leagueofgraphs);},'Profile links saved.');}
else if(kind==='strategy'){const t={id:id||uid(),name:d.name.trim(),description:(d.description||'').trim(),runePage:runeDraft?validatePage(clone(runeDraft)):null,archived:strategy(id)?.archived||false};mutate(s=>{if(id)s.strategies[s.strategies.findIndex(t=>t.id===id)]=t;else s.strategies.push(t);},'Strategy saved.');}
else if(kind==='match'){const m={...(state.matches.find(m=>m.id===id)||{}),id:id||uid(),accountId:d.accountId,strategyId:d.strategyId,sessionId:d.sessionId,result:d.result,lp:integer(d.lp,'LP change',-1000,1000,true),ts:time(d.ts,'match time'),season:d.season.trim(),patch:(d.patch||'').trim(),enemy:(d.enemy||'').trim(),support:(d.support||'').trim(),keystone:(d.keystone||'').trim(),runes:(d.runes||'').trim(),build:(d.build||'').trim(),note:(d.note||'').trim(),runePage:state.matches.find(m=>m.id===id)?.runePage||clone(strategy(d.strategyId)?.runePage||null),duration:number(d.duration,'Game duration',.1,1000,true),queueMinutes:number(d.queueMinutes,'Queue time',0,1000,true),cs:integer(d.cs,'CS',0,10000,true),kills:integer(d.kills,'Kills',0,10000,true),deaths:integer(d.deaths,'Deaths',0,10000,true),assists:integer(d.assists,'Assists',0,10000,true),matchId:(d.matchId||'').trim()};if(!id&&m.runePage){m.keystone=rune(m.runePage.primaryRunes[0])?.name||m.keystone;m.runes=pageNames(m.runePage);}
if(m.ts>Date.now()+60000)throw Error('Match time cannot be in the future.');if(!id&&state.matches.some(x=>x.accountId===m.accountId&&Math.abs(x.ts-m.ts)<60000)&&!confirm('A match for this account already exists within the same minute. Save another?'))return;mutate(s=>{if(id)s.matches[s.matches.findIndex(m=>m.id===id)]=m;else s.matches.push(m);},id?'Match corrected; all statistics updated.':'Match saved.');}
else if(kind==='session'){const x={id:id||uid(),name:d.name.trim(),season:d.season.trim(),start:time(d.start,'session start'),end:d.end?time(d.end,'session end'):null};if(x.end===null&&state.sessions.some(s=>s.end===null&&s.id!==id))throw Error('Only one session can be active at a time.');if(x.start>Date.now())throw Error('Session start cannot be in the future.');mutate(s=>{if(id)s.sessions[s.sessions.findIndex(x=>x.id===id)]=x;else s.sessions.push(x);},'Session saved.');}
else if(kind==='checkpoint'){const c={id:uid(),accountId:id,rank:d.rank,lp:integer(d.lp,'Checkpoint LP',0,DIVISIONS.indexOf(d.rank)<28?99:100000),ts:time(d.ts,'checkpoint time'),season:d.season.trim()};if(c.ts>Date.now()+60000)throw Error('Checkpoint cannot be in the future.');if(c.ts<account(id).baselineTs)throw Error('Checkpoint must be on or after the account starting rank timestamp.');mutate(s=>s.checkpoints.push(c),'Rank checkpoint saved.');}
else if(kind==='connection'){await api('/api/connection',{method:'POST',body:JSON.stringify({key:d.key})});form.reset();connectionStatus={connected:true};toast('Riot API key encrypted and saved on the server.');}
else if(kind==='link-account'){mutate(s=>{const a=s.accounts.find(a=>a.id===id);a.riotId=d.riotId.trim();a.region=d.region;},'Account identity saved.');$('#dialog').close();awaitSync(id);return;}
else if(kind==='assign-unassigned'){const ids=new Set(matches().filter(m=>!m.strategyId).map(m=>m.id));mutate(s=>{for(const m of s.matches)if(ids.has(m.id)){m.strategyId=d.strategyId;}},'Strategy assigned to selected unassigned matches.');}
else if(kind==='season'){if(state.sessions.some(s=>s.end===null))throw Error('End the active session before changing seasons.');mutate(s=>{s.season=d.season.trim();},'Season updated; history preserved.');f.season=state.season;render();return;}
else if(kind==='paste-import'){if(!await importData(d.json,form.dataset.recovery==='true'))return;}
$('#dialog').close();}catch(err){const target=form.querySelector('.form-error');if(target)target.textContent=err.message;else toast(err.message);}});
window.addEventListener('hashchange',()=>{page=0;render();window.scrollTo(0,0);});window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){blocked=true;$('#save-status').textContent='Another tab changed this data';toast('Another tab changed the workspace. Reload this tab before editing.');}});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});render();
function performanceChart(list,kind){const m=[...list].filter(m=>m.result!=='remake').sort((a,b)=>a.ts-b.ts);if(!m.length)return empty('Nothing to plot yet.','Record matches with performance details to reveal the pattern.');const colors=['#ef4444','#fca5a5','#f5f5f5','#fb7185','#9ca3af','#b91c1c'];let series=[];if(kind==='kda'){series=['kills','deaths','assists'].map((key,i)=>({name:key,color:colors[i],p:m.map((v,j)=>({x:j+1,y:v[key]})).filter(p=>p.y!==null)}));}else{series=[...new Set(m.map(x=>x.accountId))].map((id,i)=>{let w=0,n=0;return {name:account(id)?.name,color:colors[i%colors.length],p:m.filter(x=>x.accountId===id).map((v,j)=>{n++;if(v.result==='win')w++;return {x:j+1,y:kind==='wr'?100*w/n:v.cs!==null&&v.duration?v.cs/v.duration:null};}).filter(p=>p.y!==null)};});}series=series.filter(s=>s.p.length);if(!series.length)return empty('Details make the difference.','Add CS and duration or K/D/A when logging your games.');const points=series.flatMap(s=>s.p),maxX=Math.max(1,...points.map(p=>p.x)),hi=kind==='wr'?100:Math.max(1,...points.map(p=>p.y))*1.1,x=v=>40+(v-1)/Math.max(1,maxX-1)*680,y=v=>155-v/hi*130;return `<svg class="chart" viewBox="0 0 750 190" role="img" aria-label="${kind==='wr'?'Cumulative win rate per account':kind==='cs'?'CS per minute per account':'Kills, deaths and assists in chronological match order'}; missing values excluded">${[0,.5,1].map(t=>`<line x1="40" y1="${25+t*130}" x2="720" y2="${25+t*130}" stroke="#343434" stroke-dasharray="3 5"/><text x="0" y="${29+t*130}">${fmt(hi*(1-t),0)}${kind==='wr'?'%':''}</text>`).join('')}${series.map(s=>`<polyline fill="none" stroke="${s.color}" stroke-width="2" points="${s.p.map(p=>x(p.x)+','+y(p.y)).join(' ')}"/>${s.p.map(p=>`<circle cx="${x(p.x)}" cy="${y(p.y)}" r="3" fill="${s.color}"><title>${esc(s.name)} · game ${p.x}: ${fmt(p.y)}</title></circle>`).join('')}`).join('')}<text x="40" y="182">Game 1</text><text x="655" y="182">Game ${maxX}</text></svg><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.name)}</span>`).join('')}</div>`;}
function championSelect(name,label,value=''){const choices=catalog.champions.map(c=>opt(c.name,c.name,value)).join('');return select(name,label,opt('','Not recorded',value)+(value&&!catalog.champions.some(c=>c.name===value)?opt(value,value,value):'')+choices);}
