function matchDialog(id='',accountId=''){const existing=state.matches.find(m=>m.id===id),a=account(existing?.accountId||accountId)||state.accounts.find(a=>!a.archived);if(!a){toast('Add an account first.');return;}const active=state.sessions.find(s=>s.end===null&&s.season===state.season),m=existing||{accountId:a.id,strategyId:a.strategyId,sessionId:active?.id||'',result:'win',lp:null,ts:Date.now(),season:state.season,patch:catalog.version.split('.').slice(0,2).join('.'),enemy:'',support:'',keystone:'',runes:'',build:'',note:'',duration:null,queueMinutes:null,cs:null,kills:null,deaths:null,assists:null,matchId:''};dialog(existing?'Edit match':'Quick match entry',`<div class="notice">${existing&&m.source==='riot'?'Imported from Riot. Performance fields are already filled.':'Prefer automatic entry? Use ↻ Sync beside your account to fetch recent games.'}</div><form data-form="match" data-id="${esc(id)}"><div class="fields">${select('accountId','Account',state.accounts.filter(a=>!a.archived||a.id===m.accountId).map(a=>opt(a.id,`${a.name} · ${a.region}`,m.accountId)).join(''))}${select('result','Result',opt('win','Victory',m.result)+opt('loss','Defeat',m.result)+opt('remake','Remake',m.result))}${select('strategyId','Saved rune page / strategy',opt('','Unassigned',m.strategyId)+state.strategies.filter(t=>!t.archived||t.id===m.strategyId).map(t=>opt(t.id,t.name,m.strategyId)).join(''))}${input('lp','LP change · optional',m.lp,'number','min="-1000" max="1000" step="1"')}</div>${existing&&m.runePage?runeSummary(m.runePage):''}<details ${existing?'open':''} style="margin-top:18px"><summary>Lane & performance · optional</summary><div class="fields">${championSelect('enemy','Enemy bot champion',m.enemy)}${championSelect('support','Allied support',m.support)}${input('kills','Kills',m.kills,'number','min="0" max="10000" step="1"')}${input('deaths','Deaths',m.deaths,'number','min="0" max="10000" step="1"')}${input('assists','Assists',m.assists,'number','min="0" max="10000" step="1"')}${input('cs','Total CS',m.cs,'number','min="0" max="10000" step="1"')}${input('duration','Game duration (minutes)',m.duration,'number','min="0.1" max="1000" step="0.1"')}${input('queueMinutes','Queue time (minutes)',m.queueMinutes,'number','min="0" max="1000" step="0.1"')}</div></details><details style="margin-top:18px"><summary>Time, session & review · optional</summary><div class="fields">${input('ts','Match time',inputTime(m.ts),'datetime-local','required')}${select('sessionId','Session',opt('','No session',m.sessionId)+state.sessions.map(s=>opt(s.id,s.name,m.sessionId)).join(''))}${input('season','Season',m.season,'text','required maxlength="40"')}${input('patch','Patch',m.patch,'text','maxlength="150"')}${input('keystone','Keystone (filled from a saved page)',m.keystone,'text','maxlength="150"')}${input('runes','Other runes',m.runes,'text','maxlength="5000"')}${input('build','Build / items',m.build,'text','maxlength="5000"')}${input('matchId','External match ID',m.matchId,'text','maxlength="150"')}${area('note','Review note',m.note,'class="full"')}</div></details><p class="help">Only account and result are needed. All other details are optional. Champion list: Data Dragon ${esc(catalog.version)}.</p>${actions(existing?'Save corrections':'Save match')}</form>`);}
async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let body;try{body=await r.json();}catch{throw Error('The server could not answer. Reload the private tracker and try again.');}if(!r.ok){const e=new Error(body.error||'Request failed.');e.status=r.status;e.retryAfter=body.retryAfter;throw e;}return body;}
function connectDialog(){dialog('Connect Riot once',`<p class="subtitle" style="margin:0 0 18px">Riot supplies the match data used by stats sites. Save your API key here, then press Sync beside an account. Your key is encrypted on the server and excluded from backups and source code.</p><form data-form="connection">${input('key','Riot API key (not your password)','','password','required autocomplete="off" placeholder="RGAPI-…" minlength="26" maxlength="110"')}<p class="help">Development keys expire every 24 hours. For ongoing personal use, apply for a personal key. You will not need to relink each account when you replace the key.</p><a class="text-btn" href="https://developer.riotgames.com/" target="_blank" rel="noopener noreferrer">Get a key from Riot’s developer portal ↗</a>${actions('Save encrypted key')}</form>`);}
function linkDialog(a){dialog('Link this account to Riot',`<p class="subtitle" style="margin:0 0 18px">Set this once for ${esc(a.name)}. Your display nickname alone may not be the complete Riot ID.</p><form data-form="link-account" data-id="${esc(a.id)}"><div class="fields">${input('riotId','Riot ID including #tag',a.riotId,'text','required maxlength="150" placeholder="Name#TAG"')}${select('region','Server',['LAN','LAS','NA','EUW','EUNE','KR','BR','OCE','TR','RU','JP','SEA','TW','VN','ME'].map(x=>opt(x,x,a.region)).join(''))}</div>${actions('Link & fetch matches')}</form>`);}
async function awaitSync(id,older=false){if(blocked){toast('Saving is paused. Reload or recover the workspace before syncing.');return;}if(syncBusy){toast('An account is already syncing.');return;}const a=account(id);if(!a.riotId.includes('#')){linkDialog(a);return;}syncBusy=true;toast('Fetching recent ranked Jhin games from Riot…');try{const body=await api('/api/sync',{method:'POST',body:JSON.stringify({riotId:a.riotId,region:a.region,puuid:a.puuid||'',offset:older?a.historyCursor||10:0,known:state.matches.filter(m=>m.accountId===id&&m.matchId).map(m=>m.matchId).slice(-500)})});syncPending={accountId:id,body,older};const candidates=body.matches.filter(m=>!state.matches.some(x=>x.accountId===id&&x.matchId===m.matchId));dialog('Review fetched matches',`<div class="sync-summary"><span class="pill">RIOT API</span><h3>${esc(body.riotId)}</h3><p class="subtitle">${esc(body.rank)} · ${fmt(body.lp)} LP · ${body.wins===null?'Unranked':body.wins+'W / '+body.losses+'L'}<br>${candidates.length} Jhin games available to import${body.hasMore?' · more history can be loaded after saving':''}.</p></div>${body.warnings.length?'<div class="notice">'+body.warnings.map(esc).join('<br>')+'</div>':''}${candidates.length?'<div class="sync-matches">'+candidates.map(m=>`<div class="list-row"><span class="result-icon ${m.result==='loss'?'loss':''}">${m.result==='win'?'W':m.result==='loss'?'L':'R'}</span><div class="grow"><strong>${m.kills} / ${m.deaths} / ${m.assists} · ${m.cs} CS</strong><small>${date(m.ts)} · ${fmt(m.duration)} min · ${esc(championName(m.enemy)||'Lane unknown')}</small></div><span class="pill muted">${esc(rune(m.keystoneId)?.name||'Runes imported')}</span></div>`).join('')+'</div>':'<div class="empty">No new Jhin games in this batch.</div>'}<p class="help">Rank, total W/L, runes, items and match performance update automatically. Riot does not supply historical per-game LP changes here; these stay blank. Similar manual entries are reconciled by time and outcome. Importing is reversible with Undo.</p><div class="form-error" role="alert"></div><div class="form-actions">${btn('Cancel','close')}${btn('Import & update account','confirm-sync','','primary')}</div>`);}catch(e){if(e.status===428){connectDialog();}else{toast(e.message);}}finally{syncBusy=false;}}
function applySync(){if(!syncPending)return;const {accountId,body,older}=syncPending;mutate(s=>{mergeAccountSync(s,accountId,body,catalog,uid);},'Matches imported and account refreshed.');$('#dialog').close();const id=syncPending.accountId;const more=body.hasMore;syncPending=null;if(more)dialog('Account updated',`<p class="subtitle">This batch is saved. To catch up after a longer break, load ten older ranked games at a time. Already imported match IDs are skipped.</p><div class="form-actions">${btn('Done','close')}${btn('Fetch older games','more-sync',id,'gold')}</div>`);}
function assignDialog(){const n=matches().filter(m=>!m.strategyId).length;if(!n){toast('No unassigned matches in the current selection.');return;}if(!state.strategies.length){strategyDialog();return;}dialog(`Assign ${n} unassigned matches`, `<form data-form="assign-unassigned"><p class="subtitle" style="margin-bottom:18px">Applies to unassigned matches in the current filters. Existing assignments and imported rune snapshots stay intact.</p>${select('strategyId','Strategy',state.strategies.filter(t=>!t.archived).map(t=>opt(t.id,t.name,'')).join(''))}${actions('Assign strategy')}</form>`);}
// Catalog refresh requires no Riot API key. The bundled snapshot keeps selectors usable offline.
refreshCatalog().then(()=>{if(!$('#dialog').open)render();}).catch(()=>{});
function checkpointChart(){const filter=getRoute()==='overview'?{season:state.season}:f;if(filter.strategy)return empty('No per-match LP recorded.','Current-rank snapshots cover the whole account, so they are not attributed to one strategy.');const list=state.checkpoints.filter(c=>c.rank!=='Unranked'&&c.lp!==null&&(!filter.account||c.accountId===filter.account)&&(!filter.season||c.season===filter.season)&&(!filter.region||account(c.accountId)?.region===filter.region)&&(!filter.from||c.ts>=new Date(filter.from+'T00:00:00').getTime())&&(!filter.to||c.ts<=new Date(filter.to+'T23:59:59.999').getTime())).sort((a,b)=>a.ts-b.ts);if(!list.length)return empty('Your climb, without extra typing.','Sync an account to capture a verified rank snapshot. Future syncs will show how your rank changed.');const colors=['#ef4444','#fca5a5','#f5f5f5','#9ca3af'],groups=[...new Set(list.map(c=>c.accountId))].map((id,i)=>{const points=list.filter(c=>c.accountId===id);const start=rankScore(points[0].rank,points[0].lp);return {id,color:colors[i%colors.length],points:points.map(c=>({...c,value:rankScore(c.rank,c.lp)-start}))};});const low=Math.min(0,...groups.flatMap(g=>g.points.map(c=>c.value))),high=Math.max(1,...groups.flatMap(g=>g.points.map(c=>c.value))),t0=list[0].ts,t1=list.at(-1).ts,x=t=>40+(t-t0)/Math.max(1,t1-t0)*680,y=v=>155-(v-low)/(high-low)*130;return `<svg class="chart" viewBox="0 0 750 190" role="img" aria-label="Verified rank change since the first snapshot for each account, expressed in division-equivalent LP">${[0,.5,1].map(t=>`<line x1="40" y1="${25+t*130}" x2="720" y2="${25+t*130}" stroke="#343434" stroke-dasharray="3 5"/><text x="0" y="${29+t*130}">${Math.round(high-t*(high-low))}</text>`).join('')}${groups.map(g=>`<polyline fill="none" stroke="${g.color}" stroke-width="2" points="${g.points.map(p=>x(p.ts)+','+y(p.value)).join(' ')}"/>${g.points.map(p=>`<circle cx="${x(p.ts)}" cy="${y(p.value)}" r="3" fill="${g.color}"><title>${esc(account(g.id)?.name)} · ${esc(p.rank)} ${p.lp} LP · ${date(p.ts)}</title></circle>`).join('')}`).join('')}<text x="40" y="182">${date(t0)}</text><text x="610" y="182">${date(t1)}</text></svg><div class="legend">${groups.map(g=>`<span><i style="background:${g.color}"></i>${esc(account(g.id)?.name)}</span>`).join('')}</div><p class="help">Verified rank change since each account’s first snapshot. This is not per-match LP or hidden MMR.</p>`;}

async function copyAccountName(id,button){
  const a=account(id);
  if(!a)return;
  const name=a.name;
  let copied=false;
  try{
    if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(name);copied=true;}
  }catch{}
  if(!copied){
    const field=document.createElement('textarea');
    field.value=name;
    field.setAttribute('readonly','');
    field.style.cssText='position:fixed;left:0;top:0;opacity:0;pointer-events:none';
    document.body.appendChild(field);
    try{field.focus();field.select();copied=document.execCommand('copy');}catch{}
    finally{field.remove();button.focus({preventScroll:true});}
  }
  if(!copied){
    dialog('Copy account name',`<label>Account name<input id="copy-account-manual" value="${esc(name)}" readonly></label><p class="help">Press Ctrl+C or Command+C to copy the selected account name.</p><div class="form-actions">${btn('Done','close')}</div>`);
    const field=$('#copy-account-manual');field.focus();field.select();
    return;
  }
  clearTimeout(button.copyTimer);
  button.textContent='✓';
  button.setAttribute('aria-label','Copied account name: '+name);
  button.title='Account name copied';
  toast('Account name copied: '+name);
  button.copyTimer=setTimeout(()=>{
    button.textContent='IV';
    button.setAttribute('aria-label','Copy account name: '+name);
    button.title='Copy account name: '+name;
  },1800);
}

function latestMatchCard(){
  const m=[...state.matches].sort((a,b)=>b.ts-a.ts)[0];
  if(!m)return `<section class="latest-match latest-empty" aria-labelledby="latest-match-title"><div><div class="kicker">LATEST MATCH</div><h2 id="latest-match-title">Your next match starts here.</h2><p>Log a game or sync an account to see its result and performance here.</p></div><div class="latest-actions">${btn('＋ Log match','match','','primary')}${btn('View accounts & sync →','go-accounts','','secondary')}</div></section>`;
  const a=account(m.accountId),outcome=m.result==='win'?'Victory':m.result==='loss'?'Defeat':'Remake';
  const kda=[m.kills,m.deaths,m.assists].map(n=>n===null?'—':fmt(n,0)).join(' / ');
  const measuredCS=m.cs===null?'—':fmt(m.cs,0),rate=m.cs!==null&&m.duration?fmt(m.cs/m.duration)+' CS / min':'Total creep score';
  return `<section class="latest-match ${m.result==='loss'?'latest-loss':''}" aria-labelledby="latest-match-title"><div class="latest-heading"><div><div class="kicker">LATEST MATCH · ${esc(m.season)}</div><h2 id="latest-match-title"><span class="latest-result">${outcome}</span> <span class="latest-account">${esc(a?.riotId||a?.name||'Account')}</span></h2><p>${date(m.ts)} · ${esc(nameStrategy(m.strategyId))}${m.patch?' · Patch '+esc(m.patch):''}</p></div>${m.matchId&&a?.puuid?btn('Review lane','review-lane',m.id,'primary'):''}${btn('Review match ↗','edit-match',m.id,'secondary')}</div><div class="latest-details"><div class="latest-stat"><span>K / D / A</span><strong>${kda}</strong><small>${m.enemy?'vs '+esc(m.enemy):'Enemy champion not recorded'}</small></div><div class="latest-stat"><span>CREEP SCORE</span><strong>${measuredCS}</strong><small>${rate}</small></div><div class="latest-stat"><span>DURATION</span><strong>${m.duration?fmt(m.duration)+' min':'—'}</strong><small>${m.support?'Support: '+esc(m.support):'Support not recorded'}</small></div><div class="latest-stat"><span>LP CHANGE</span><strong>${m.lp===null?'—':signed(m.lp)}</strong><small>${m.lp===null?'Not recorded':m.source==='riot'?'Added manually':'Recorded LP change'}</small></div></div></section>`;
}

async function syncAllAccounts(){
 if(blocked||syncBusy||bulkRunning||syncPending){toast('Finish the current sync or reload the workspace before syncing all accounts.');return;}
 if(!state.accounts.length){toast('Add an account first.');return;}
 try{const status=await api('/api/connection');if(!status.connected){connectDialog();return;}}catch(e){toast(e.message);return;}
 if(syncBusy||bulkRunning)return;
 bulkRunning=true;syncBusy=true;const resumeKey='jhin_bulk_resume_v1';let resume={};
 try{resume=JSON.parse(localStorage.getItem(resumeKey)||'{}');}catch{}
 const ids=Array.isArray(resume.ids)&&resume.season===state.season&&resume.ids.length?resume.ids:state.accounts.map(a=>a.id),results=[];let lastRequest=0;
 const saveResume=(remaining,retryAt=0)=>{try{localStorage.setItem(resumeKey,JSON.stringify({ids:remaining,season:state.season,retryAt}));}catch{}};
 saveResume(ids,resume.retryAt);
 
 const progress=text=>{bulkProgress=text;if(getRoute()==='accounts')accounts();};
 try{for(let i=0;i<ids.length;i++){
 const a=account(ids[i]);if(!a){continue;}if(!a.riotId.includes('#')){results.push({name:a.name,error:'Add the full Riot ID including #tag in Edit.'});saveResume(ids.slice(i+1));continue;}
 progress(`Refreshing ${i+1} / ${ids.length}: ${a.name} · waiting for Riot sync cooldown…`);
 await new Promise(resolve=>setTimeout(resolve,Math.max(0,15500-(Date.now()-lastRequest),(resume.retryAt||0)-Date.now())));
 if(blocked)throw Error('Workspace changed in another tab. Reload before continuing.');
 progress(`Refreshing ${i+1} / ${ids.length}: ${a.name}…`);lastRequest=Date.now();
 try{const body=await api('/api/sync',{method:'POST',body:JSON.stringify({riotId:a.riotId,region:a.region,puuid:a.puuid||'',offset:0,known:state.matches.filter(m=>m.accountId===a.id&&m.matchId).map(m=>m.matchId).slice(-500)})});
 mutate(next=>mergeAccountSync(next,a.id,body,catalog,uid));results.push({name:a.name,warnings:body.warnings||[]});if(body.retryAfter){saveResume(ids.slice(i),Date.now()+body.retryAfter*1000);break;}saveResume(ids.slice(i+1));
 }catch(e){results.push({name:a.name,error:e.message});if([401,403,428,429].includes(e.status)){saveResume(ids.slice(i),Date.now()+(e.retryAfter||0)*1000);break;}saveResume(ids.slice(i+1));}
 }
 }catch(e){results.push({name:'Sync stopped',error:e.message});}
 finally{bulkRunning=false;syncBusy=false;const done=results.filter(r=>!r.error).length;progress(`${done} / ${ids.length} accounts refreshed. ${results.filter(r=>r.error).length} need attention.`);
 dialog('Account refresh complete',`<p>Refreshed ${done} of ${ids.length} accounts. Current level, rank, W/L and recent ranked Jhin matches are saved. Older history can still be fetched with individual Sync.</p>${results.map(r=>`<div class="list-row"><div><strong>${esc(r.name)}</strong><small>${esc(r.error||'Updated'+(r.warnings.length?' · '+r.warnings.join(' · '):''))}</small></div></div>`).join('')}${results.length<ids.length?'<p>Remaining accounts were not refreshed. Check your key or rate limit, then try again.</p>':''}<div class="form-actions">${btn('Done','close','','primary')}</div>`);
 }
}


function honorBadges(a){const label=a.honorLevel==null?'Honor not recorded':'Honor level '+a.honorLevel;return `<button type="button" class="honor-badge honor-${a.honorLevel??'unknown'}" data-action="honor" data-id="${esc(a.id)}" aria-label="Edit ${esc(label)} for ${esc(a.name)}" title="${esc(label)} · click to edit"><svg viewBox="0 0 24 26" aria-hidden="true"><path d="M12 2 22 7 19 19 12 24 5 19 2 7Z"/><path d="m7 11 5-5 5 5-5 9Z"/></svg><span>${a.honorLevel??'?'}</span></button>${a.honorLocked?`<button type="button" class="restriction-badge" data-action="honor" data-id="${esc(a.id)}" aria-label="Honor progression locked · edit" title="Honor progression locked">♜</button>`:''}${(a.restrictions||[]).map(k=>RESTRICTIONS[k]?`<button type="button" class="restriction-badge" data-action="honor" data-id="${esc(a.id)}" aria-label="${RESTRICTIONS[k][1]} · edit" title="${RESTRICTIONS[k][1]}">${RESTRICTIONS[k][0]}</button>`:'').join('')}`;}
function honorDialog(id){const a=account(id);dialog('Honor & restrictions',`<p>${esc(a.riotId||a.name)}</p><form data-form="honor" data-id="${esc(id)}">${select('honorLevel','Current honor level',opt('','Not recorded',a.honorLevel??'')+[0,1,2,3,4,5].map(n=>opt(n,'Level '+n+(n===0?' · reset / dishonorable':''),a.honorLevel)).join(''))}<p class="help">Record the level currently shown in the client. Restrictions do not automatically change this value; update it here when a penalty resets honor.</p><fieldset><legend>Current restrictions</legend>${Object.entries(RESTRICTIONS).map(([k,[icon,label]])=>`<label class="check-label"><input type="checkbox" name="${k}" ${(a.restrictions||[]).includes(k)?'checked':''}> ${icon} ${label}</label>`).join('')}<label class="check-label"><input type="checkbox" name="honorLocked" ${a.honorLocked?'checked':''}> Honor progression locked</label></fieldset><p class="help">Manually maintained. Riot account sync preserves these settings. Clear restrictions here when they expire.</p>${actions('Save honor & restrictions')}</form>`);}

function overviewSummary(){
 const combined=state.accounts.reduce((t,a)=>{const n=totals(state,a);t.wins+=n.wins;t.losses+=n.losses;return t;},{wins:0,losses:0}),n=combined.wins+combined.losses,p=percent(combined.wins,combined.losses);
 const peaks=state.accounts.flatMap(a=>[{...rankAt(state,a),account:a}, {rank:a.rank,lp:a.lp,account:a},...state.checkpoints.filter(c=>c.accountId===a.id).map(c=>({...c,account:a}))]).filter(r=>r.rank!=='Unranked').sort((a,b)=>DIVISIONS.indexOf(b.rank)-DIVISIONS.indexOf(a.rank)||(b.lp??-1)-(a.lp??-1));const peak=peaks[0];
 const recent=state.matches.filter(m=>m.season===state.season&&m.result!=='remake').sort((a,b)=>a.ts-b.ts).slice(-20);
 return `<section class="overview-summary"><div class="summary-intro"><span class="kicker">ALL ACCOUNTS · ${esc(state.season)}</span><h1>Your ranked journey</h1><p>${state.accounts.length} accounts · ${n} combined ranked games</p><div class="summary-totals"><strong>${combined.wins}<small>WINS</small></strong><strong>${combined.losses}<small>LOSSES</small></strong><strong>${wr(p)}<small>WIN RATE</small></strong></div></div><div class="summary-peak rank-${esc(peak?.rank.split(' ')[0].toLowerCase()||'unranked')}"><svg viewBox="0 0 100 110" role="img" aria-label="Highest recorded rank emblem"><path d="M50 5 86 23 79 76 50 103 21 76 14 23Z"/><path d="M50 19 70 37 50 80 30 37Z"/><path d="M25 83 5 50M75 83l20-33"/></svg><strong>${esc(peak?.rank||'Unranked')}${peak?.lp!=null?' · '+peak.lp+' LP':''}</strong><small>HIGHEST RECORDED RANK</small><span>${esc(peak?.account.riotId||peak?.account.name||'Sync an account to begin')}</span></div><div class="summary-form"><h3>Combined results</h3><div class="summary-results" role="img" aria-label="${combined.wins} wins and ${combined.losses} losses"><span style="width:${p??0}%"></span></div><p>${combined.wins} W / ${combined.losses} L · starting balances included</p><h3>Last ${recent.length} recorded games</h3><div class="form-strip">${recent.length?recent.map(m=>`<span class="${m.result}" title="${esc(account(m.accountId)?.riotId||'Account')} · ${date(m.ts)}">${m.result==='win'?'W':'L'}</span>`).join(''):'<span>No recorded games yet</span>'}</div></div></section>`;
}
function bestAccountCards(){const rows=state.accounts.filter(a=>!a.archived&&!(a.restrictions||[]).some(k=>k==='ban'||k==='suspension')).map(a=>{const recent=state.matches.filter(m=>m.accountId===a.id&&m.season===state.season&&m.result!=='remake').sort((x,y)=>y.ts-x.ts).slice(0,20), n=recent.length,w=recent.filter(m=>m.result==='win').length,t={wins:w,losses:n-w};return {a,t,n,p:percent(w,n),score:interval(w,n)?.[0]??0};}).filter(x=>x.n>=10&&x.p>50).sort((a,b)=>b.score-a.score||b.n-a.n).slice(0,4);return `<div class="panel-body"><p class="help">Ranked by the conservative estimate of win rate in up to 20 recent recorded Jhin games (95% Wilson lower bound). At least 10 games and over 50% wins; banned or suspended accounts are excluded. This is a performance signal, not a guarantee.</p><div class="best-accounts">${rows.length?rows.map(({a,t,n,p},i)=>`<article><span class="kicker">#${i+1} · ${n} GAMES</span><h3>${esc(a.riotId||a.name)}</h3><p>${esc(a.name)} · ${esc(rankAt(state,a).rank)}</p><strong class="wr-high">${wr(p)}</strong><span>${t.wins} W / ${t.losses} L · recent</span><p>Season: ${wr(percent(...Object.values(totals(state,a))))} · ${laneAccountSummary(a.id)}</p></article>`).join(''):'<p>No accounts qualify yet. Sync accounts or record more games to build a useful comparison.</p>'}</div></div>`;}

function laneCacheKey(m){return 'jhin_lane_v1:'+m.accountId+':'+m.matchId;}
function cachedLane(m){try{return JSON.parse(localStorage.getItem(laneCacheKey(m))||'null');}catch{return null;}}
function laneAccountSummary(id){
 const points=state.matches.filter(m=>m.accountId===id&&m.season===state.season&&m.matchId).sort((a,b)=>b.ts-a.ts).slice(0,20).map(m=>cachedLane(m)?.points?.find(p=>p.ms>=600000&&p.ms<630000)).filter(Boolean);
 return points.length?`${signed(Math.round(points.reduce((s,p)=>s+p.gold,0)/points.length))} gold @10 avg · ${points.length} reviewed`:'No lane reviews yet';
}
async function reviewLane(id){
 const m=state.matches.find(x=>x.id===id),a=account(m?.accountId);if(!m?.matchId||!a?.puuid)return;
 const show=lane=>{
 const time=ms=>ms==null?'—':Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0');
 const points=lane.points,lo=Math.min(-1,...points.map(p=>p.gold)),hi=Math.max(1,...points.map(p=>p.gold)),y=n=>100-(n-lo)/(hi-lo)*80,x=ms=>20+ms/Math.max(1,points.at(-1)?.ms||0)*420;
 dialog('Jhin lane review',`<p>${esc(a.riotId)}${lane.enemy?' vs '+esc(lane.enemy):' · ADC matchup unavailable'}</p><div class="metrics">${[10,15].map(n=>{const p=points.find(p=>p.ms>=n*60000&&p.ms<n*60000+30000);return metric('AT '+n+' MIN',p?signed(p.gold)+' gold':'—',p?signed(p.cs)+' lane CS':'No comparable frame');}).join('')}${metric('FIRST DEATH',time(lane.firstDeath),lane.firstDeath==null?'No death recorded':'Game time')}${metric('FIRST COMPLETED ITEM',time(lane.firstItem?.ms),esc(lane.firstItem?.name||(lane.itemTimingAvailable?'No completed item found':'Patch item data unavailable')))}</div>${points.length>1?`<svg class="chart" viewBox="0 0 460 125" role="img" aria-label="Jhin gold difference versus enemy ADC over game time"><line x1="20" y1="${y(0)}" x2="440" y2="${y(0)}" stroke="#777"/><polyline fill="none" stroke="#ff8390" stroke-width="2" points="${points.map(p=>x(p.ms)+','+y(p.gold)).join(' ')}"/><text x="20" y="120">0 min</text><text x="395" y="120">${time(points.at(-1).ms)}</text></svg>`:''}<p class="help">Gold and lane CS are relative to the opposing ADC; CS excludes jungle monsters.</p><div class="form-actions">${btn('Done','close','','primary')}</div>`);
 };
 const saved=cachedLane(m);if(saved){show(saved);return;}
 if(syncBusy){toast('Wait for account sync to finish before fetching a lane review.');return;}
 syncBusy=true;
 try{toast('Fetching lane timeline from Riot…');const lane=await api('/api/lane',{method:'POST',body:JSON.stringify({matchId:m.matchId,puuid:a.puuid,region:a.region})});try{localStorage.setItem(laneCacheKey(m),JSON.stringify(lane));}catch{}show(lane);}
 catch(e){if(e.status===428)connectDialog();else toast(e.message);}
 finally{syncBusy=false;}
}
function snapshotChanges(){
 const rows=state.accounts.flatMap(a=>{const [now,prev]=state.checkpoints.filter(c=>c.accountId===a.id&&c.season===state.season&&c.source==='riot').sort((x,y)=>y.ts-x.ts);if(!prev)return [];const comparable=now.rank===prev.rank&&now.lp!=null&&prev.lp!=null;return [`<div class="list-row"><span class="grow">${esc(a.riotId||a.name)}<small>${date(prev.ts)} → ${date(now.ts)}</small></span><strong>${comparable?signed(now.lp-prev.lp)+' LP':esc(prev.rank+' → '+now.rank)}</strong></div>`];});
 return rows.length?`<details><summary>Changes between latest syncs</summary>${rows.join('')}</details>`:'';
}


document.addEventListener('change',e=>{
 if(!['comparison-mode','comparison-patch','comparison-rank'].includes(e.target.id))return;
 if(e.target.id==='comparison-mode')comparisonMode=e.target.value;
 if(e.target.id==='comparison-patch')comparisonPatch=e.target.value;
 if(e.target.id==='comparison-rank')comparisonRank=e.target.value;
 $('#comparison-results').innerHTML=comparisonRows();
});
function comparisonRows(){
 const groups=new Map();
 for(const m of state.matches){
  if(m.season!==state.season||m.result==='remake'||(comparisonPatch&&m.patch!==comparisonPatch)||(comparisonRank&&rankAt(state,account(m.accountId),m.ts).rank.split(' ')[0]!==comparisonRank))continue;
  const key=comparisonMode==='item'?cachedLane(m)?.firstItem?.name:m[comparisonMode];
  if(!key)continue;
  const g=groups.get(key)||{n:0,w:0,lane:[]};g.n++;g.w+=m.result==='win';const p=cachedLane(m)?.points?.find(p=>p.ms>=600000&&p.ms<630000);if(p)g.lane.push(p.gold);groups.set(key,g);
 }
 const rows=[...groups].sort((a,b)=>b[1].n-a[1].n);
 return rows.length?`<div class="table-scroll"><table><thead><tr><th>Group</th><th>Games</th><th>Win rate</th><th>Gold @10</th></tr></thead><tbody>${rows.map(([key,g])=>`<tr><td>${esc(key)}</td><td>${g.n}${g.n<10?' · small sample':''}</td><td>${wr(percent(g.w,g.n-g.w))}</td><td>${g.lane.length?signed(Math.round(g.lane.reduce((a,b)=>a+b,0)/g.lane.length))+' · '+g.lane.length+' reviewed':'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">No qualifying matches. First item and gold comparisons use saved lane reviews.</p>';
}
function comparisonPanel(){
 const patches=[...new Set(state.matches.map(m=>m.patch).filter(Boolean))].sort((a,b)=>b.localeCompare(a,undefined,{numeric:true}));
 return `<div class="panel-body"><div class="filters">${select('comparison-mode','Compare by',[['enemy','Enemy ADC'],['support','Allied support'],['keystone','Keystone'],['item','First completed item']].map(([v,l])=>opt(v,l,comparisonMode)).join('')).replace('name="comparison-mode"','name="comparison-mode" id="comparison-mode"')}${select('comparison-patch','Patch',opt('','All patches',comparisonPatch)+patches.map(p=>opt(p,p,comparisonPatch)).join('')).replace('name="comparison-patch"','name="comparison-patch" id="comparison-patch"')}${select('comparison-rank','Rank',opt('','All ranks',comparisonRank)+[...TIERS,'Master','Grandmaster','Challenger'].map(p=>opt(p,p,comparisonRank)).join('')).replace('name="comparison-rank"','name="comparison-rank" id="comparison-rank"')}</div><div id="comparison-results">${comparisonRows()}</div></div>`;
}
